create or replace function public.refresh_reading_health_signals() returns integer language plpgsql security definer set search_path=public,pg_temp as $$
declare v_count integer:=0; begin
 with stats as (select publication_id,chapter_id,count(*)::int sessions,count(distinct viewer_id)::int learners,avg(max_progress_percent)::numeric avg_progress,count(*) filter(where completed_at is not null)::numeric/nullif(count(*),0) completion_ratio from vibe_reading_sessions where chapter_id is not null and started_at>=now()-interval '90 days' group by publication_id,chapter_id having count(*)>=5),
 inserted as (insert into curriculum_content_health_signals(publication_id,chapter_id,outcome_id,signal_type,severity,score,evidence_count,evidence,status,first_detected_at,last_detected_at)
 select s.publication_id,s.chapter_id,(select l.outcome_id from chapter_learning_outcome_links l where l.chapter_id=s.chapter_id order by l.sequence nulls last,l.created_at limit 1),'reading_completion',case when coalesce(s.completion_ratio,0)<0.25 and coalesce(s.avg_progress,0)<40 then 'high' else 'medium' end,greatest(1-coalesce(s.completion_ratio,0),1-coalesce(s.avg_progress,0)/100),s.sessions,jsonb_build_object('sessions',s.sessions,'learners',s.learners,'avg_progress_percent',round(s.avg_progress,2),'completion_ratio',round(s.completion_ratio,4),'window_days',90),'open',now(),now() from stats s where coalesce(s.completion_ratio,0)<0.5 and coalesce(s.avg_progress,0)<70 and not exists(select 1 from curriculum_content_health_signals h where h.chapter_id=s.chapter_id and h.signal_type='reading_completion' and h.status='open') returning id)
 select count(*) into v_count from inserted; return v_count; end $$;
revoke all on function public.refresh_reading_health_signals() from public,anon,authenticated; grant execute on function public.refresh_reading_health_signals() to service_role;
do $$ begin if exists(select 1 from pg_extension where extname='pg_cron') then perform cron.unschedule(jobid) from cron.job where jobname='vibeschool-content-intelligence-cycle'; perform cron.schedule('vibeschool-content-intelligence-cycle','17 * * * *',$cron$select public.refresh_reading_health_signals(); select public.run_content_intelligence_cycle('scheduled');$cron$); end if; end $$;